(async () => {
  const before = (await import('/api/v1/qa/baseline-purify.mjs')).default;
  const after = (await import('/node_modules/.vite/deps/dompurify.js')).default;
  const {marked} = await import('/node_modules/.vite/deps/marked.js');
  const {data} = await (await fetch('/api/v1/qa/inputs')).json();
  const html = marked.parse(data.markdown, {breaks:true,gfm:true});
  const cases = [
    {surface:'legal',html,options:{}},
    {surface:'announcement-popup',html,options:{}},
    {surface:'announcement-bell',html,options:{}},
    {surface:'custom-markdown',html:marked.parse(data.custom_markdown,{breaks:true,gfm:true}),options:{ADD_TAGS:['iframe'],ADD_ATTR:['allowfullscreen','frameborder','src']}},
    {surface:'sidebar-svg',html:data.svg,options:{USE_PROFILES:{svg:true,svgFilters:true}}}
  ];
  const comparisons=cases.map(test=>{
    const oldHtml=before.sanitize(test.html,test.options),newHtml=after.sanitize(test.html,test.options);
    if(oldHtml!==newHtml) throw new Error('Sanitizer output changed for '+test.surface);
    return {surface:test.surface,equal:true,html_length:newHtml.length,iframe_preserved:test.surface==='custom-markdown'?newHtml.includes('<iframe'):null,handler_attributes_removed:!(/onload=|onclick=|javascript:/i.test(newHtml))};
  });
  const content=document.querySelector('.legal-document-content');
  if(!content) throw new Error('Legal content missing');
  await Promise.all([...content.querySelectorAll('img')].map(img=>img.decode()));
  const result={before_version:before.version,after_version:after.version,comparisons,anonymous:localStorage.getItem('auth_token')===null,legal:{headings:content.querySelectorAll('h2').length,table_rows:content.querySelectorAll('table tr').length,list_items:content.querySelectorAll('li').length,inline_code:content.querySelector('code')?.textContent,image_loaded:content.querySelector('img')?.naturalWidth>0,dangerous_attributes:content.querySelectorAll('[onload],[onclick],a[href^="javascript:"]').length,xss_not_executed:window.__qaXss!==true},page_overflow:document.documentElement.scrollWidth>innerWidth};
  if(!result.anonymous || result.legal.dangerous_attributes || !result.legal.xss_not_executed || !result.legal.image_loaded || result.page_overflow) throw new Error(JSON.stringify(result));
  return result;
})()
